using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MilitaryAuthorityPolicyTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction a)=>new(new("request:authority-policy/"+s.Revision+"/"+a),a);
 static void Send(WorldSession s,NewMilitaryAction a){var r=s.DecideNewMilitary(Input(s,a),s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Start(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);var i=Input(s,NewMilitaryAction.Request) with{AuthorityPolicy=NewGameMilitary.AuthorityContract};var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s;}
 static WorldSession Pickup(){var s=Start();At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);return s;}
 [Fact]public void ExplicitPolicyRecordsActualOfferAndPermissionAndOnlyPickupGetsScopedGrant(){var s=Start();var w=s.DiagnosticSnapshot();Assert.Empty(w.NewMilitary!.Authority!.Proofs);Assert.Empty(w.NewMilitary.Authority.Grants);At(s,1);w=s.DiagnosticSnapshot();Assert.Single(w.NewMilitary!.Authority!.Proofs);Assert.False(NewGameMilitary.View(w).CanAccept);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,3);w=s.DiagnosticSnapshot();Assert.Equal(2,w.NewMilitary!.Authority!.Proofs.Length);Assert.Empty(w.NewMilitary.Authority.Grants);Assert.False(NewGameMilitary.View(w).CanPickup);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);w=s.DiagnosticSnapshot();var grant=Assert.Single(w.NewMilitary!.Authority!.Grants);Assert.Equal(w.NewMilitary.Terms.Case,grant.Case);Assert.Equal(w.NewMilitary.Terms.Owner,grant.Owner);Assert.Null(w.CommandMandates);Assert.All(w.Units,u=>Assert.Equal(grant.Owner,u.Organization));new WorldSession(w);}
 [Fact]public void EndedServiceCannotBecomePermissionBeforeItsPhysicalRefusalIsKnown(){var s=Start();At(s,2);Open(s);var c=NewGameService.View(s.DiagnosticSnapshot()).Cases.Single();Assert.Equal(ResultCode.Accepted,s.DecideService(new(new("request:release-before-permission"),CareerAction.RequestRelease,c.Case),s.PlayerControl,s.Revision).Code);At(s,3);Assert.False(NewGameService.BoundAt(s.DiagnosticSnapshot(),new("person:shingen"),s.Seconds,s.Revision));Send(s,NewMilitaryAction.Accept);var before=NewGameMilitary.View(s.DiagnosticSnapshot()).Status;At(s,4);var w=s.DiagnosticSnapshot();Assert.Contains(w.NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Refused);Assert.DoesNotContain(w.NewMilitary.Events,e=>e.Effect==MilitaryEffect.Permission);Assert.Single(w.NewMilitary.Authority!.Proofs);Assert.Empty(w.NewMilitary.Authority.Grants);Assert.Equal(before,NewGameMilitary.View(w).Status);At(s,5);Open(s);Assert.Contains("不承諾",NewGameMilitary.View(s.DiagnosticSnapshot()).Status);new WorldSession(s.DiagnosticSnapshot());}
 [Theory][InlineData("office")][InlineData("owner")][InlineData("missing-proof")][InlineData("action")][InlineData("null-proof")]
 public void ForgedSavedAuthorityIsRejected(string change){var s=Pickup();var w=s.DiagnosticSnapshot();var x=w.NewMilitary!.Authority!;if(change=="office")x.Proofs[1]=x.Proofs[1] with{Source=x.Proofs[1].Source with{Office=new("office:forged")}};if(change=="owner")x.Proofs[1]=x.Proofs[1] with{Source=x.Proofs[1].Source with{Owner=new("org:forged")}};if(change=="missing-proof")w.NewMilitary=w.NewMilitary with{Authority=x with{Proofs=x.Proofs[..1]}};if(change=="action")x.Grants[0].Mandate.Actions[0]=RegionalAction.Engage;if(change=="null-proof")x.Proofs[0]=null!;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void PickupAndReturnAuthorityRestoreIdenticalFutureWithoutPropertyTransfer(){var s=Pickup();var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored}){Send(v,NewMilitaryAction.Report);At(v,v.Seconds+1);Send(v,NewMilitaryAction.Return);At(v,v.Seconds+2);Open(v);}var a=s.DiagnosticSnapshot();Assert.Equal(ContractJson.CanonicalHash(a),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));var grant=Assert.Single(a.NewMilitary!.Authority!.Grants);Assert.NotNull(grant.UntilRevision);Assert.All(a.Units,u=>Assert.Equal(a.NewMilitary.Terms.Owner,u.Organization));Assert.All(a.ResourceLots,l=>Assert.Equal(a.NewMilitary.Terms.Owner,l.Owner));new WorldSession(a);}
 [Fact]public void LegacyOmissionDoesNotRetroactivelyInstallSourceAuthority(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);var i=Input(s,NewMilitaryAction.Request);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);At(s,2);var w=s.DiagnosticSnapshot();Assert.Null(w.NewMilitary!.Authority);Assert.DoesNotContain("AuthorityPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(i)));Assert.DoesNotContain("\"Authority\"",System.Text.Encoding.UTF8.GetString(ContractJson.Write(w.NewMilitary)));new WorldSession(ContractJson.Read<ContractWorld>(ContractJson.Write(w)));}
 [Fact]public void UnknownPolicyAndPolicyOnAnotherActionAreAtomic(){var s=Start();foreach(var a in new[]{NewMilitaryAction.Request,NewMilitaryAction.Inquire}){var w=s.DiagnosticSnapshot();var i=Input(s,a) with{AuthorityPolicy=a==NewMilitaryAction.Request?"unknown":NewGameMilitary.AuthorityContract};string before=ContractJson.CanonicalHash(w);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}}
}
